SELECT time, CAST(metric_0001 AS DOUBLE) AS metric_0001, CAST(metric_0500 AS DOUBLE) AS metric_0500, CAST(metric_1000 AS DOUBLE) AS metric_1000, CAST(metric_1500 AS DOUBLE) AS metric_1500, CAST(metric_2000 AS DOUBLE) AS metric_2000 FROM wide2000 WHERE time >= '2024-09-23' AND time < '2025-01-01' ORDER BY time
